def solve(nums: list):
    ordered = sorted(nums)
    middle = len(ordered) // 2
    if len(ordered) % 2:
        return ordered[middle]
    return (ordered[middle - 1] + ordered[middle]) / 2.0

def solve(intervals: list) -> list:
    if not intervals:
        return []

    ordered = sorted(intervals, key=lambda interval: interval[0])
    merged = [[ordered[0][0], ordered[0][1]]]

    for start, end in ordered[1:]:
        if start <= merged[-1][1]:
            merged[-1][1] = max(merged[-1][1], end)
        else:
            merged.append([start, end])

    return merged

def solve(items: list) -> list:
    result = []
    for item in items:
        if item not in result:
            result.append(item)
    return result

def solve(s: str) -> str:
    result = []
    for position, char in enumerate(s):
        if position > 0 and char.isupper():
            result.append("_")
        result.append(char.lower())
    return "".join(result)

def solve(s: str) -> dict:
    result = {}
    for segment in s.split(";"):
        if "=" in segment:
            key, value = segment.split("=", 1)
            result[key.strip()] = value.strip()
    return result

def solve(s: str, n: int) -> str:
    if len(s) <= n:
        return s
    return s[:n - 3] + "..."

def solve(year: int, month: int, day: int) -> int:
    month_lengths = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
    if year % 400 == 0 or (year % 4 == 0 and year % 100 != 0):
        month_lengths[1] = 29
    return sum(month_lengths[:month - 1]) + day

def solve(items: list, k: int) -> list:
    if not items:
        return []
    shift = k % len(items)
    return items[-shift:] + items[:-shift] if shift else items[:]

def solve(s: str) -> str:
    digits_left = sum(ch.isdigit() for ch in s)
    result = []

    for ch in s:
        if ch.isdigit():
            digits_left -= 1
            result.append("*" if digits_left >= 4 else ch)
        else:
            result.append(ch)

    return "".join(result)

def solve(words: list) -> str:
    if not words:
        return ""
    prefix = words[0]
    for word in words[1:]:
        length = 0
        while length < len(prefix) and length < len(word) and prefix[length] == word[length]:
            length += 1
        prefix = prefix[:length]
        if not prefix:
            break
    return prefix

def solve(n: int, base: int) -> str:
    digits = "0123456789abcdef"
    if n == 0:
        return "0"
    result = []
    while n > 0:
        result.append(digits[n % base])
        n //= base
    return "".join(reversed(result))

def solve(a: str, b: str) -> int:
    parts_a = a.split(".")
    parts_b = b.split(".")

    for index in range(max(len(parts_a), len(parts_b))):
        value_a = int(parts_a[index]) if index < len(parts_a) else 0
        value_b = int(parts_b[index]) if index < len(parts_b) else 0

        if value_a < value_b:
            return -1
        if value_a > value_b:
            return 1

    return 0

def solve(a: str, b: str) -> bool:
    return sorted(ch for ch in a.casefold() if not ch.isspace()) == sorted(
        ch for ch in b.casefold() if not ch.isspace()
    )

def solve(part: int, total: int) -> int:
    if total == 0:
        return 0
    return (2 * part * 100 + total) // (2 * total)

def solve(s: str):
    digits = ''.join(c for c in s if c.isdigit())
    if len(digits) == 11 and digits[0] == '1':
        digits = digits[1:]
    if len(digits) != 10:
        return None
    return f'({digits[:3]}) {digits[3:6]}-{digits[6:]}'

def solve(nums: list, target: int) -> int:
    left, right = 0, len(nums) - 1

    while left <= right:
        mid = (left + right) // 2
        if nums[mid] == target:
            return mid
        if nums[mid] < target:
            left = mid + 1
        else:
            right = mid - 1

    return -1

def solve(s: str) -> list:
    if not s.strip():
        return []

    result = []
    for item in s.split(","):
        item = item.strip()
        if "-" in item:
            start, end = map(int, item.split("-"))
            result.extend(range(start, end + 1))
        else:
            result.append(int(item))
    return result

def solve(s: str) -> list:
    if s.startswith("#"):
        s = s[1:]
    if len(s) == 3:
        s = "".join(ch * 2 for ch in s)
    return [int(s[i:i + 2], 16) for i in (0, 2, 4)]

def solve(n: int) -> str:
    last_two = n % 100
    if 11 <= last_two <= 13:
        suffix = "th"
    else:
        suffix = {1: "st", 2: "nd", 3: "rd"}.get(n % 10, "th")
    return f"{n}{suffix}"
